from base.exceptions import EntityBadRequestErrorfrom base.service import BaseServicefrom entities.container import Container, ContainerType as ctfrom helpers.search import Paginationfrom repositories.container import ContainerRepositoryfrom schemas.channel import ChannelCreatefrom services.container import ContainerServicefrom services.join_request import JoinRequestServicefrom services.subscribe import SubscribeServicefrom sqlalchemy.ext.asyncio import AsyncSessionfrom utils.post import generate_slugchannels = [    ct.PUBLIC_CHANNEL,    ct.PRIVATE_CHANEL]class PublicChannelService(ContainerService):    def __init__(self, session: AsyncSession):        super().__init__(session)        self.subs_service = SubscribeService(session)    async def subscribe(self, user_id: int, channel_id: int):        await self.subs_service.create_subscribe(user_id=user_id, container_id=channel_id)class PrivateChannelService(ContainerService):    def __init__(self, session: AsyncSession):        super().__init__(session)        self.jr_service = JoinRequestService(session)        self.subs_service = SubscribeService(session)    async def send_jr(self, user_id: int, channel_id: int):        await self.subs_service.check_already_exists(user_id=user_id, container_id=channel_id)        await self.jr_service.send_jr(user_id=user_id, channel_id=channel_id)    async def process_jr(            self, user_id: int,            jr_id: int, approve: bool    ):        jr = await self.jr_service.get_item_by_id(jr_id)        channel = await self.get_item_by_id(jr.container_id)        if channel.author_id != user_id:            raise EntityBadRequestError("Недостаточно прав")        if approve:            await self.subs_service.create_subscribe(                user_id=user_id, container_id=jr.container_id            )        await self.jr_service.delete_item_by_id(jr.id)    async def get_jrs(self, user_id: int, channel: Container, pagination: Pagination):        if user_id != channel.author_id:            raise EntityBadRequestError("Недостаточно прав")        return await self.jr_service.get_items_by(            container_id=channel.id,            pagination=pagination        )class ChannelService(BaseService[Container, ContainerRepository]):    def __init__(self, session: AsyncSession):        super().__init__(Container, session, ContainerRepository)    async def create_channel(self, user_id: int, channel: ChannelCreate) -> Container:        await self.check_already_exists(            slug=channel.slug, type=channels        )        channel.slug = generate_slug(channel.slug)        return await self.create_item(            author_id=user_id, **channel.dict(), type=channels[channel.is_private]        )    async def get_subscribers(self, user_id: int, channel: Container, pagination: Pagination):        if channel.author_id != user_id:            raise EntityBadRequestError("Недостаточно прав")        subs_service = SubscribeService(self.session)        return await subs_service.get_container_subscribers(container_id=channel.id, pagination=pagination)